import sys
from collections import deque

def bfs(n, m, k, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    start = None
    end = None

    # Find the positions of S and T
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                end = (i, j)

    # Initialize the queue for BFS
    queue = deque([(start[0], start[1], 0, set(), '')])
    visited = set()
    visited.add((start[0], start[1], frozenset()))

    while queue:
        x, y, dist, types, path = queue.popleft()

        # If we reach the end, return the path
        if (x, y) == end:
            return path

        # Explore neighbors
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                new_type = grid[nx][ny]
                if new_type.islower():
                    new_types = types | {new_type}
                else:
                    new_types = types

                if len(new_types) <= k and (nx, ny, frozenset(new_types)) not in visited:
                    visited.add((nx, ny, frozenset(new_types)))
                    queue.append((nx, ny, dist + 1, new_types, path + new_type))

    return "-1"

# Read input
input = sys.stdin.read
data = input().split()
n = int(data[0])
m = int(data[1])
k = int(data[2])
grid = data[3:]

# Find the path
result = bfs(n, m, k, grid)

# Print the result
print(result)
